#include <stdio.h>

int main() {
    int N;
    scanf("%d", &N);

    int dario = 0, xerxes = 0;

    for (int i = 0; i < N; i++) {
        int D, X;
        scanf("%d %d", &D, &X);

        int diff = (X - D + 5) % 5;

        if (diff == 1 || diff == 2) {
            dario++;
        } else {
            xerxes++;
        }
    }

    if (dario > xerxes) {
        printf("dario\n");
    } else {
        printf("xerxes\n");
    }

    return 0;
}
